#include <stdio.h>
#include <stdlib.h>

int miller_rabin(long long n, int k) {
    if (n == 2 || n == 3)
        return 1;
    if (n <= 1 || n % 2 == 0)
        return 0;
    long long s = 0;
    long long r = n - 1;
    while ((r & 1) == 0) {
        s++;
        r /= 2;
    }
    for (int i = 0; i < k; i++) {
        long long a = rand() % (n - 2) + 2;
        long long x = 1;
        for (long long j = 0; j < r; j++) {
            x = (x * a) % n;
        }
        if (x != 1 && x != n - 1) {
            int j = 1;
            while (j < s && x != n - 1) {
                x = (x * x) % n;
                if (x == 1)
                    return 0;
                j++;
            }
            if (x != n - 1)
                return 0;
        }
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    long long n = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n < 2) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (miller_rabin(n, 5)) {
        printf("PRIME\n");
    } else {
        printf("NOT_PRIME\n");
    }
    return 0;
}
